begin;
-- Prefix all application objects to avoid overwriting existing project tables.
create table public.pm_profiles(id uuid primary key references auth.users on delete cascade,full_name text not null default '',company text not null default '',role text not null default 'BUYER' check(role in ('BUYER','SELLER','ADMIN')),status text not null default 'active' check(status in ('active','pending','locked')),created_at timestamptz not null default now());
create function public.pm_bootstrap() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.pm_profiles(id,full_name,company,role,status) values(new.id,left(coalesce(new.raw_user_meta_data->>'full_name',''),150),left(coalesce(new.raw_user_meta_data->>'company',''),200),case when new.raw_user_meta_data->>'role'='SELLER' then 'SELLER' else 'BUYER' end,case when new.raw_user_meta_data->>'role'='SELLER' then 'pending' else 'active' end);return new;end; $$;
create trigger pm_auth_created after insert on auth.users for each row execute function public.pm_bootstrap();
insert into public.pm_profiles(id) select id from auth.users on conflict do nothing;
create function public.pm_active() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.pm_profiles where id=auth.uid() and status in ('active','pending')); $$;
create function public.pm_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.pm_profiles where id=auth.uid() and status='active' and role='ADMIN'); $$;
create table public.pm_records(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.pm_profiles on delete cascade,kind text not null check(kind in ('assessment','roadmap','roi')),input jsonb not null check(pg_column_size(input)<=64000),result jsonb not null check(pg_column_size(result)<=256000),created_at timestamptz not null default now());
create index pm_records_owner_time on public.pm_records(user_id,created_at desc);
create table public.pm_kpis(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.pm_profiles on delete cascade,code text not null check(code in ('otif','emptyKm','inventoryAccuracy')),value numeric not null check(value between 0 and 100),target numeric not null check(target between 0 and 100),period text not null check(period ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),source text not null check(char_length(source) between 1 and 300),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,code,period));
create index pm_kpis_owner_period on public.pm_kpis(user_id,period desc);
create table public.pm_solutions(id text primary key,data jsonb not null,published boolean not null default false,approved boolean not null default false);
create table public.pm_knowledge(id uuid primary key default gen_random_uuid(),external_id text unique,title text not null check(char_length(title) between 1 and 300),content text not null check(char_length(content) between 1 and 15000),kind text not null default 'knowledge' check(kind in ('knowledge','news')),url text check(url is null or url ~ '^https://'),source_sheet text,source_references jsonb not null default '[]',metadata jsonb not null default '{}',review_status text not null default 'Bản nháp',published boolean not null default false,updated_at timestamptz not null default now());
create table public.pm_reference(external_id text primary key,category text not null check(category in ('source','handoff')),data jsonb not null,approved boolean not null default false);
create table public.pm_tickets(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.pm_profiles on delete cascade,request_id uuid not null,subject text not null check(char_length(subject) between 1 and 1500),department text not null default 'CSKH' check(department in ('CSKH','Kỹ thuật','Chuyên môn','Tài chính')),status text not null default 'open' check(status in ('open','assigned','resolved')),assigned_to uuid references public.pm_profiles,created_at timestamptz not null default now(),unique(user_id,request_id));
create index pm_tickets_owner_time on public.pm_tickets(user_id,created_at desc);
create table public.pm_api_quota(user_id uuid not null references public.pm_profiles on delete cascade,hour timestamptz not null,used integer not null default 1,primary key(user_id,hour));
create function public.pm_consume_quota() returns boolean language plpgsql security definer set search_path='' as $$ declare n integer;begin if auth.uid() is null or not public.pm_active() then return false;end if;insert into public.pm_api_quota(user_id,hour) values(auth.uid(),date_trunc('hour',now())) on conflict(user_id,hour) do update set used=public.pm_api_quota.used+1 where public.pm_api_quota.used<30 returning used into n;return n is not null;end; $$;
alter table public.pm_profiles enable row level security;
alter table public.pm_records enable row level security;
alter table public.pm_kpis enable row level security;
alter table public.pm_solutions enable row level security;
alter table public.pm_knowledge enable row level security;
alter table public.pm_reference enable row level security;
alter table public.pm_tickets enable row level security;
alter table public.pm_api_quota enable row level security;
create policy pm_profiles_read on public.pm_profiles for select to authenticated using(id=auth.uid() or public.pm_admin());
create policy pm_profiles_admin on public.pm_profiles for update to authenticated using(public.pm_admin()) with check(public.pm_admin());
create policy pm_records_read on public.pm_records for select to authenticated using(public.pm_active() and (user_id=auth.uid() or public.pm_admin()));
-- These are immutable owner self-reports, never billing evidence or verified certification.
create policy pm_records_insert on public.pm_records for insert to authenticated with check(user_id=auth.uid() and public.pm_active() and exists(select 1 from public.pm_profiles where id=auth.uid() and role='BUYER'));
create policy pm_kpis_read on public.pm_kpis for select to authenticated using(public.pm_active() and (user_id=auth.uid() or public.pm_admin()));
create policy pm_kpis_insert on public.pm_kpis for insert to authenticated with check(user_id=auth.uid() and public.pm_active() and exists(select 1 from public.pm_profiles where id=auth.uid() and role='BUYER'));
create policy pm_kpis_update on public.pm_kpis for update to authenticated using(user_id=auth.uid() and public.pm_active() and exists(select 1 from public.pm_profiles where id=auth.uid() and role='BUYER')) with check(user_id=auth.uid() and public.pm_active());
create policy pm_solutions_read on public.pm_solutions for select to authenticated using(public.pm_active() and ((published and approved) or public.pm_admin()));
create policy pm_solutions_admin on public.pm_solutions for all to authenticated using(public.pm_admin()) with check(public.pm_admin());
create policy pm_knowledge_read on public.pm_knowledge for select to authenticated using(public.pm_active() and (published or public.pm_admin()));
create policy pm_knowledge_admin on public.pm_knowledge for all to authenticated using(public.pm_admin()) with check(public.pm_admin());
create policy pm_reference_admin on public.pm_reference for all to authenticated using(public.pm_admin()) with check(public.pm_admin());
create policy pm_tickets_read on public.pm_tickets for select to authenticated using(public.pm_active() and (user_id=auth.uid() or public.pm_admin()));
create policy pm_tickets_insert on public.pm_tickets for insert to authenticated with check(user_id=auth.uid() and public.pm_active() and status='open' and assigned_to is null);
create policy pm_tickets_admin on public.pm_tickets for update to authenticated using(public.pm_admin()) with check(public.pm_admin());
revoke all on public.pm_profiles,public.pm_records,public.pm_kpis,public.pm_solutions,public.pm_knowledge,public.pm_reference,public.pm_tickets,public.pm_api_quota from anon,authenticated;
grant select on public.pm_profiles,public.pm_records,public.pm_kpis,public.pm_solutions,public.pm_knowledge,public.pm_reference,public.pm_tickets to authenticated;
grant update(role,status) on public.pm_profiles to authenticated;
grant insert on public.pm_records,public.pm_tickets to authenticated;
grant insert on public.pm_kpis to authenticated;
grant update(value,target,source,updated_at) on public.pm_kpis to authenticated;
grant insert,update,delete on public.pm_solutions,public.pm_knowledge,public.pm_reference to authenticated;
grant update(status,department,assigned_to) on public.pm_tickets to authenticated;
revoke all on function public.pm_bootstrap(),public.pm_active(),public.pm_admin(),public.pm_consume_quota() from public;
grant execute on function public.pm_active(),public.pm_admin(),public.pm_consume_quota() to authenticated;
commit;
